{
  "tools": [
    {
      "name": "get_selection",
      "title": "Get Selection",
      "toolset": "scene",
      "description": "What's selected in the editor - the game objects and components the user (or you) has picked.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "GameObjects": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                }
              },
              "required": []
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_assign_asset",
      "title": "Assign Asset",
      "toolset": "hammer",
      "description": "Apply an asset to nodes the way dropping it onto them in Hammer does - a material paints every face of the meshes (or just the selected faces, in Faces mode), a model swaps a prop's model. Give node ids, or nothing to apply to the current selection. Selects the nodes it applied to. The user can undo this.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "asset": {
            "type": "string",
            "description": "The material or model asset path."
          },
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Node ids to apply to. Empty applies to the current selection."
          }
        },
        "required": [
          "asset"
        ]
      }
    },
    {
      "name": "hammer_focus_nodes",
      "title": "Focus Nodes",
      "toolset": "hammer",
      "description": "Select nodes and frame every Hammer view on them, like the user pressing the frame selection key - the quickest way to show the user something, or to aim hammer_screenshot at it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "The node ids to frame."
          }
        },
        "required": [
          "ids"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_get_node",
      "title": "Get Node",
      "toolset": "hammer",
      "description": "Everything about one map node - transform, parent and children, and depending on its kind: an entity's class and every keyvalue, a mesh's face materials, a game object's id and components, or an instance's target.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "integer",
            "description": "The node id, from hammer_find_nodes or hammer_get_selection."
          },
          "includeComponentProperties": {
            "type": "boolean",
            "description": "Include the full serialized properties of a game object's components, not just their types.",
            "default": false
          }
        },
        "required": [
          "id"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Angles": {
            "type": "string"
          },
          "Scale": {
            "type": "string"
          },
          "ChildCount": {
            "type": "integer"
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          },
          "EntityClassTitle": {
            "type": "string"
          },
          "KeyValues": {
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          },
          "Materials": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {}
              },
              "required": []
            }
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "InstanceTarget": {
            "type": "integer"
          },
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_get_selection",
      "title": "Get Selection",
      "toolset": "hammer",
      "description": "What's selected in Hammer - the selection mode (Groups, Objects, Meshes, Vertices, Edges, Faces...), the pivot position, and the selected nodes. In a component mode like Faces the nodes list is the objects owning the selection.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_list_commands",
      "title": "List Commands",
      "toolset": "hammer",
      "description": "Hammer's named commands - everything its key bindings and menus can do, like GroupSelection, HideUnselected, SelectSimilar, MirrorHorizontal, SnapToGrid, CreatePrefabFromSelection, FrameAllViews or BuildMap. Run one with hammer_run_command.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Case insensitive substring to filter by, e.g. 'select' or 'prefab'. Empty lists all."
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_run_command",
      "title": "Run Command",
      "toolset": "hammer",
      "description": "Run a Hammer command by name, exactly as if the user pressed its key binding. Most act on the selection, so select first with hammer_select - e.g. select nodes then run GroupSelection. A few open dialogs and will wait for the user. hammer_list_commands lists them all.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "The command name, as hammer_list_commands shows it."
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "name": "hammer_select",
      "title": "Select",
      "toolset": "hammer",
      "description": "Change Hammer's selection - select nodes by id and/or everything using an asset, optionally switching selection mode first. Selecting is how you show the user what you mean, and some tools (hammer_run_command, hammer_assign_asset) act on the selection. Returns the new selection.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Node ids to select. Empty selects nothing by id."
          },
          "usingAsset": {
            "type": "string",
            "description": "Also select every node using this asset - a model or material path."
          },
          "add": {
            "type": "boolean",
            "description": "Add to the current selection instead of replacing it.",
            "default": false
          },
          "mode": {
            "type": "string",
            "enum": [
              "Groups",
              "Objects",
              "Meshes",
              "Verticies",
              "Edges",
              "Faces",
              "Nav",
              "Tiles"
            ],
            "description": "Switch selection mode first - Groups, Objects or Meshes. Empty keeps the current mode."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_status",
      "title": "Status",
      "toolset": "hammer",
      "description": "Whether Hammer is open and what map it's editing - the map's asset path, unsaved changes, how many nodes of each kind it has, the selection mode and count, and the material active in Hammer's material browser. Start here before any other hammer_ tool. If Hammer isn't open, hammer_open_map opens a map in it.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Open": {
            "type": "boolean"
          },
          "MapOpen": {
            "type": "boolean"
          },
          "Map": {
            "type": "string"
          },
          "File": {
            "type": "string"
          },
          "HasUnsavedChanges": {
            "type": "boolean"
          },
          "NodeCounts": {
            "type": "object",
            "additionalProperties": {
              "type": "integer"
            }
          },
          "SelectionMode": {
            "type": "string"
          },
          "SelectedCount": {
            "type": "integer"
          },
          "CurrentMaterial": {
            "type": "string"
          },
          "ViewCount": {
            "type": "integer"
          }
        },
        "required": []
      }
    },
    {
      "name": "set_selection",
      "title": "Set Selection",
      "toolset": "scene",
      "description": "Replace the editor selection. Selecting something highlights it for the user - useful for showing them what you're talking about. An empty list clears the selection.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Game object or component ids to select."
          }
        },
        "required": [
          "ids"
        ]
      }
    }
  ],
  "total": 128
}

{
  "tools": [
    {
      "name": "asset_compile",
      "title": "Asset Compile",
      "toolset": "asset",
      "description": "Recompile an asset from its source file. Compile errors and warnings land in the console - check read_console after a failure.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          },
          "full": {
            "type": "boolean",
            "description": "Force a full recompile instead of an incremental one.",
            "default": false
          }
        },
        "required": [
          "path"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Success": {
            "type": "boolean"
          },
          "Path": {
            "type": "string"
          },
          "CompiledFile": {
            "type": "string"
          },
          "Hint": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_dependencies",
      "title": "Asset Dependencies",
      "toolset": "asset",
      "description": "Walk an asset's relationships - the assets it references (uses), the assets that depend on it, or the assets it was generated from. Deep recurses the whole chain, e.g. a model's materials and their textures.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          },
          "relation": {
            "type": "string",
            "enum": [
              "References",
              "Dependants",
              "Parents"
            ],
            "description": "Which direction to walk.",
            "default": "References"
          },
          "deep": {
            "type": "boolean",
            "description": "Recurse instead of returning only direct relationships.",
            "default": false
          },
          "type": {
            "type": "string",
            "description": "Filter results to one asset type - a file extension or friendly name. See asset_types."
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Path": {
            "type": "string"
          },
          "Relation": {
            "type": "string"
          },
          "Total": {
            "type": "integer",
            "description": "How many related assets exist, beyond what's shown."
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_files",
      "title": "Asset Files",
      "toolset": "asset",
      "description": "The loose disk files behind an asset - the input files it's built from (.fbx, .tga, .png...), extra content and game files it ships with, and reference paths that couldn't be resolved to assets.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Path": {
            "type": "string"
          },
          "SourceFile": {
            "type": "string"
          },
          "CompiledFile": {
            "type": "string"
          },
          "InputFiles": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "AdditionalContentFiles": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "AdditionalGameFiles": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "UnresolvedReferences": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_find_by_file",
      "title": "Asset Find By File",
      "toolset": "asset",
      "description": "Find the assets built from a loose disk file - which models use this .fbx, which textures use this .png. Matches the end of the path, so a filename is enough.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "file": {
            "type": "string",
            "description": "File path or filename, e.g. chair.fbx"
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          }
        },
        "required": [
          "file"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer"
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_info",
      "title": "Asset Info",
      "toolset": "asset",
      "description": "Everything about one asset - name, type, source and compiled file paths, compile state, tags, cloud package, and how many assets it references and is used by. Explore those relationships with asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search. Absolute paths work too."
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string"
          },
          "Path": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "Extension": {
            "type": "string"
          },
          "IsGameResource": {
            "type": "boolean"
          },
          "SourceFile": {
            "type": "string"
          },
          "CompiledFile": {
            "type": "string"
          },
          "IsCompiled": {
            "type": "boolean"
          },
          "IsCompiledAndUpToDate": {
            "type": "boolean"
          },
          "IsCompileFailed": {
            "type": "boolean"
          },
          "CanRecompile": {
            "type": "boolean"
          },
          "IsCloud": {
            "type": "boolean"
          },
          "IsTransient": {
            "type": "boolean"
          },
          "IsProcedural": {
            "type": "boolean"
          },
          "IsTrivialChild": {
            "type": "boolean"
          },
          "Package": {
            "type": "string"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "ReferenceCount": {
            "type": "integer"
          },
          "DependantCount": {
            "type": "integer"
          },
          "LastOpened": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_read",
      "title": "Asset Read",
      "toolset": "asset",
      "description": "Read a game resource asset's raw json - the actual data of a prefab, sound event, clothing definition or any other GameResource type. Doesn't work on binary assets like models and textures.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "asset_search",
      "title": "Asset Search",
      "toolset": "asset",
      "description": "Search the asset system by keywords and type. An empty query lists every asset, so use limit and offset to page through. Returns relative asset paths - pass one to asset_info, asset_compile, asset_read or asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Space separated keywords. Every keyword must match the asset's path or one of its tags. Empty matches everything."
          },
          "type": {
            "type": "string",
            "description": "Filter to one asset type - a file extension (vmdl, vmat, prefab) or friendly name (Model, Material). See asset_types."
          },
          "projectOnly": {
            "type": "boolean",
            "description": "Only assets belonging to the currently open project, excluding engine content and cloud downloads.",
            "default": false
          },
          "unreferencedOnly": {
            "type": "boolean",
            "description": "Only assets nothing else references - useful for finding unused assets. Note map files and code can use an asset without the asset system knowing.",
            "default": false
          },
          "compileFailedOnly": {
            "type": "boolean",
            "description": "Only assets whose last compile failed.",
            "default": false
          },
          "uncompiledOnly": {
            "type": "boolean",
            "description": "Only assets with no compiled version at all.",
            "default": false
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many assets matched in total, beyond this page."
          },
          "Showing": {
            "type": "integer"
          },
          "Offset": {
            "type": "integer"
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
